 if(enhancementTypes.includes(type))return enhancementCommand(input,type,p,role);
 demand(allowed[type]?.includes(role),'This action requires a different demonstration role.');const state=hydrateState(input),who=actor(role);let s=state.shipments.find(x=>x.id===p.shipment);let result='';
