export function draft(state,s){const principal=state.principals.find(p=>p.id===s.principal)?.name,warehouse=state.warehouses.find(w=>w.id===s.warehouse)?.name;return `DRAFT — operator review required\n\nPlease arrange ${state.trucks.find(t=>t.id===s.truck)?.name} for ${s.id}.\nPrincipal: ${principal}\nPickup: ${warehouse}\nDestination: ${s.destination}\nPlanned departure: ${s.departure}\nLoad: ${s.lines.map(l=>`${l.packed} × ${l.sku}`).join(', ')}\nVehicle: ${s.vehicle||'[awaiting confirmation]'}\nDriver: ${s.driver||'[awaiting confirmation]'}\nPlease confirm vehicle availability and agreed freight.\n\nThis is a local template draft. No message has been sent.`;}
